import re

import django.db.models.deletion
from django.db import migrations, models

XRAY_PORT_RE = re.compile(r"^socks5h?://xray:(\d+)/?(?:#.*)?$", re.IGNORECASE)
PENDING_KEYS = ("settings", "last_json", "challenge_hint")   # the old "waiting for a code" state in device_settings


def link_configs_and_clean_pending(apps, schema_editor):
    """Accounts on a dedicated xray port get the config behind it (it stays with them from now on); the old
    pending-login keys leave device_settings (a running login now lives in pending_login), keeping the phone."""
    Account = apps.get_model("discovery", "InstagramEngineAccount")
    ProxyConfig = apps.get_model("discovery", "ProxyConfig")
    by_port = {port: pk for pk, port in ProxyConfig.objects.filter(local_port__isnull=False)
               .exclude(local_port__in=(1080, 8080)).values_list("pk", "local_port")}
    for acc in Account.objects.all().only("pk", "proxy_url", "proxy_config", "device_settings"):
        fields = []
        m = XRAY_PORT_RE.match((acc.proxy_url or "").strip())
        if m and int(m.group(1)) in by_port and acc.proxy_config_id is None:
            acc.proxy_config_id = by_port[int(m.group(1))]
            fields.append("proxy_config")
        ds = acc.device_settings
        if isinstance(ds, dict) and any(k in ds for k in PENDING_KEYS):
            ds = dict(ds)
            pending_phone = ds.get("settings") if isinstance(ds.get("settings"), dict) else {}
            if not (isinstance(ds.get("device_settings"), dict) and ds["device_settings"].get("model")) \
                    and isinstance(pending_phone.get("device_settings"), dict) and isinstance(pending_phone.get("uuids"), dict):
                ds["device_settings"], ds["uuids"] = pending_phone["device_settings"], pending_phone["uuids"]
            for key in PENDING_KEYS:
                ds.pop(key, None)
            acc.device_settings = ds
            fields.append("device_settings")
        if fields:
            acc.save(update_fields=fields)


